<template>
  <el-dialog :model-value="modelValue" :title="detail?.model?.name ? detail.model.name+' · 模型核对' : '模型核对'" width="min(1240px,96vw)" class="model-review-dialog" align-center :close-on-click-modal="false" :close-on-press-escape="!saving" :show-close="!saving" :before-close="close" @update:model-value="value=>!saving&&emit('update:modelValue',value)">
    <el-alert v-if="error" :title="error" type="error" :closable="false"><el-button v-if="!saving" text @click="load">重新加载</el-button></el-alert>
    <div v-loading="loading" class="review-content">
      <template v-if="detail">
        <div class="review-state-line"><el-tag :type="detail.review?.valid && detail.review.status==='approved' ? 'success' : 'warning'">{{ modelReviewLabel(detail.review) }}</el-tag><span v-if="detail.review">{{ detail.review.actorName }} · {{ time(detail.review.reviewedAt) }}</span></div>
        <div class="review-comparison">
          <section class="review-model-pane">
            <ModelPreview v-if="detail.model.modelUrl && detail.version.available" :key="detail.version.hash" :model-url="detail.model.modelUrl" :title="detail.model.name" :front-rotation-y="Number(detail.model.frontRotationY)||0" :initial-angle=".55" height="430px" :allow-unreviewed="true" :show-observation-details="false" :inspect-meshes="true" :selected-mesh-id="selectedMeshId" @mesh-inventory="receiveMeshes" @observe="observeMesh" />
            <el-empty v-else :description="detail.version.reason || '当前模型没有可读取的三维文件'" />
            <details v-if="meshes.length" class="review-meshes" open><summary>实际网格 · {{ meshes.length }} 项</summary><p>点击网格查看高亮；未命名网格的结构含义仍待确认。</p><div class="review-mesh-list"><button v-for="mesh in meshes" :key="mesh.id" type="button" :aria-pressed="selectedMeshId===mesh.id" :class="{active:selectedMeshId===mesh.id}" @click="selectedMeshId=mesh.id"><strong>{{ mesh.name || '未命名网格' }}</strong><small>{{ mesh.vertexCount || 0 }} 顶点 · {{ mesh.triangleCount || 0 }} 三角面</small></button></div></details>
          </section>
          <section class="review-evidence-pane">
            <h3>对照备件与资料</h3>
            <el-select v-model="form.referencePartId" aria-label="本次对照关联备件" placeholder="选择本次对照的关联备件" clearable :disabled="saving || !detail.parts.length"><el-option v-for="part in detail.parts" :key="part.id" :value="part.id" :label="[part.code,part.name,part.spec].filter(Boolean).join(' · ')" /></el-select>
            <dl v-if="referencePart" class="review-part-meta"><div><dt>物料编码</dt><dd>{{ referencePart.code }}</dd></div><div><dt>名称</dt><dd>{{ referencePart.name }}</dd></div><div><dt>规格 / 型号</dt><dd>{{ referencePart.spec || '尚未填写' }}</dd></div><div v-if="referencePart.brand"><dt>品牌</dt><dd>{{ referencePart.brand }}</dd></div></dl>
            <p v-else class="review-hint">{{ detail.parts.length ? '选择关联备件后，对照其编码、规格与实物照片。' : '此模型暂无关联备件，可记录现场对照依据，不能仅凭模型名称判断通过。' }}</p>
            <section class="review-photo"><h4>备件实物照片</h4><el-image v-if="referencePart?.partImageUrl" :src="referencePart.partImageUrl" :preview-src-list="[referencePart.partImageUrl]" fit="contain" preview-teleported><template #error><span>实物照片暂不可用，请补充有效照片后核对。</span></template></el-image><div v-else class="review-photo-empty">{{ referencePart ? '该备件尚未上传实物照片' : '请选择对照备件' }}</div></section>
            <section v-if="detail.model.imageUrl" class="review-photo"><h4>模型参考图</h4><el-image :src="detail.model.imageUrl" :preview-src-list="[detail.model.imageUrl]" fit="contain" preview-teleported><template #error><span>参考图暂不可用</span></template></el-image></section>
          </section>
        </div>
        <section v-if="canSubmit" class="review-decision">
          <h3>登记本次核对结论</h3>
          <el-radio-group v-model="form.status" :disabled="saving" aria-label="核对结论"><el-radio-button value="approved">核对通过</el-radio-button><el-radio-button value="needs_fix">需修正</el-radio-button><el-radio-button value="pending">待核对</el-radio-button></el-radio-group>
          <label class="review-field">对照依据<el-select v-model="form.referenceType" :disabled="saving" aria-label="对照依据"><el-option label="备件实物照片" value="physical_photo" /><el-option label="模型参考图 / 厂家资料" value="manufacturer_reference" /><el-option label="现场实物核对" value="onsite" /></el-select></label>
          <div class="review-checks"><el-checkbox v-model="form.checks.identity" :disabled="saving">已核对备件编码、规格及型号身份</el-checkbox><el-checkbox v-model="form.checks.outline" :disabled="saving">已对照实物 / 资料核对外形轮廓</el-checkbox><el-checkbox v-model="form.checks.interfaces" :disabled="saving">已核对可见接口、端子或安装连接位置</el-checkbox></div>
          <label class="review-field">核对说明<el-input v-model="form.note" :disabled="saving" type="textarea" :rows="3" maxlength="2000" show-word-limit :placeholder="form.status==='approved' ? '写明对照了哪件实物或哪份资料、外形和接口的核对情况；至少10字' : '说明缺少哪些资料、哪些外形或接口需要修正'" /></label>
          <el-alert v-if="saveError" :title="saveError" type="error" :closable="false"><el-button v-if="!saving" text @click="load">重新加载当前版本</el-button></el-alert>
          <div class="review-save"><span>核对账号、时间和当前模型版本由系统记录</span><el-button type="primary" :loading="saving" @click="save">保存核对结论</el-button></div>
        </section>
        <p v-else class="review-hint">此账号可查看核对资料；核对结论由有权限维护此模型的管理员登记。</p>
        <details class="review-version"><summary>模型版本与核对范围</summary><p>本次核对记录针对当前外形、可见接口和对照备件，不会自动命名未确认网格。</p><dl><div><dt>当前版本</dt><dd>{{ detail.version.hash }}</dd></div><div><dt>模型文件 SHA256</dt><dd>{{ detail.version.modelFileHash || '无可用文件' }}</dd></div></dl></details>
        <section class="review-history"><h3>核对记录</h3><article v-for="entry in detail.history || []" :key="entry.id"><header><strong>{{ modelReviewStatusLabel(entry.status) }}</strong><span>{{ entry.actorName }} · {{ time(entry.reviewedAt) }}</span></header><p>{{ entry.note }}</p><small>版本 {{ String(entry.versionHash || '').slice(0,16) }}<template v-if="entry.stale"> · 此记录对应旧版本</template><template v-if="entry.referenceSnapshot?.part?.code"> · 备件 {{ entry.referenceSnapshot.part.code }}</template></small></article><p v-if="!detail.history?.length" class="review-hint">尚无人工核对记录。</p></section>
      </template>
    </div>
  </el-dialog>
</template>
<script setup>
import { computed, onBeforeUnmount, reactive, ref, watch } from 'vue'
import { ElMessage } from 'element-plus'
import ModelPreview from './ModelPreview.vue'
import { getPartModelReview, savePartModelReview } from '../api'
import { buildModelReviewPayload, modelReviewLabel, modelReviewStatusLabel } from '../utils/model-review.mjs'
const props=defineProps({modelValue:Boolean,modelId:[String,Number],canReview:Boolean}),emit=defineEmits(['update:modelValue','saved'])
const detail=ref(null),loading=ref(false),saving=ref(false),error=ref(''),saveError=ref(''),meshes=ref([]),selectedMeshId=ref('')
const form=reactive({status:'pending',note:'',referencePartId:'',referenceType:'onsite',checks:{identity:false,outline:false,interfaces:false}})
let generation=0,requestId='',payloadKey=''
const referencePart=computed(()=>detail.value?.parts?.find(part=>Number(part.id)===Number(form.referencePartId)))
const canSubmit=computed(()=>props.canReview && detail.value?.permissions?.canReview===true)
const time=value=>value?new Date(value).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai',hour12:false}):'—'
function resetForm(){Object.assign(form,{status:'pending',note:'',referencePartId:'',referenceType:'onsite',checks:{identity:false,outline:false,interfaces:false}});requestId='';payloadKey='';saveError.value=''}
async function load(){if(!props.modelValue||!props.modelId||saving.value)return;const token=++generation;loading.value=true;error.value='';detail.value=null;meshes.value=[];selectedMeshId.value='';resetForm();try{const response=await getPartModelReview(props.modelId);if(token!==generation||!props.modelValue)return;detail.value=response.data}catch(cause){if(token===generation)error.value=cause.response?.data?.msg||cause.message||'核对资料读取失败'}finally{if(token===generation)loading.value=false}}
function receiveMeshes(items){meshes.value=Array.isArray(items)?items:[];if(!meshes.value.some(item=>item.id===selectedMeshId.value))selectedMeshId.value=''}
function observeMesh(item){if(meshes.value.some(mesh=>mesh.id===item?.id))selectedMeshId.value=item.id}
async function save(){if(saving.value||!canSubmit.value)return;saveError.value='';try{if(form.status==='approved'&&!meshes.value.length)throw new Error('请先等待模型显示并查看实际网格后再确认通过');const key=JSON.stringify(form);if(!requestId||key!==payloadKey){requestId=crypto.randomUUID();payloadKey=key}const payload=buildModelReviewPayload(form,detail.value,requestId);saving.value=true;const token=generation,modelId=props.modelId,response=await savePartModelReview(modelId,payload);if(token!==generation||!props.modelValue)return;detail.value=response.data;emit('saved',{modelId,reviewDecision:detail.value.review,version:detail.value.version});ElMessage.success('模型核对结论已保存');resetForm()}catch(cause){saveError.value=cause.response?.data?.msg||cause.message||'核对记录保存失败；填写内容已保留'}finally{saving.value=false}}
function close(done){if(saving.value)return;generation++;emit('update:modelValue',false);if(typeof done==='function')done()}
watch(()=>[props.modelValue,props.modelId],()=>{if(props.modelValue)load();else{generation++;detail.value=null;meshes.value=[];selectedMeshId.value='';resetForm()}},{immediate:true})
onBeforeUnmount(()=>{generation++})
</script>
<style scoped>
.review-content{min-height:160px}.review-state-line{display:flex;flex-wrap:wrap;align-items:center;gap:12px;margin-bottom:16px;color:#738196;font-size:12px}.review-comparison{display:grid;grid-template-columns:minmax(0,1.6fr) minmax(260px,1fr);gap:20px}.review-model-pane,.review-evidence-pane{min-width:0}.review-evidence-pane h3,.review-decision h3,.review-history h3{margin:0 0 14px;font-size:15px}.review-evidence-pane :deep(.el-select){width:100%}.review-part-meta{margin:12px 0;display:grid;gap:8px}.review-part-meta>div{display:grid;grid-template-columns:86px minmax(0,1fr);gap:8px}.review-part-meta dt{color:#7d899b}.review-part-meta dd{margin:0;overflow-wrap:anywhere}.review-photo h4{font-size:13px;margin:14px 0 8px}.review-photo :deep(.el-image){display:grid;place-items:center;width:100%;height:190px;border:1px solid #e2e8ef;border-radius:8px;background:#f7f9fc}.review-photo-empty{display:grid;place-items:center;min-height:110px;padding:14px;background:#f5f7fa;border-radius:8px;color:#8190a4;font-size:12px}.review-hint{font-size:12px;color:#77879a;line-height:1.8}.review-meshes{margin-top:12px}.review-meshes summary,.review-version summary{cursor:pointer;color:#52687d}.review-meshes p{font-size:12px;color:#77879a}.review-mesh-list{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:7px;max-height:184px;overflow:auto;padding:3px}.review-mesh-list button{min-width:0;min-height:49px;padding:8px;text-align:left;border:1px solid #dde5ee;border-radius:7px;background:#f7f9fc;color:#536a80;font:inherit;cursor:pointer}.review-mesh-list strong{display:block;font-weight:500;font-size:12px;overflow-wrap:anywhere}.review-mesh-list small{font-size:10px;color:#8491a3}.review-mesh-list button.active{border-color:#578d9d;background:#eaf5f7;color:#225c6c}.review-decision{margin-top:24px;padding-top:20px;border-top:1px solid #e2e8ef}.review-field{display:block;margin-top:15px;color:#5d7085;font-size:12px}.review-field :deep(.el-select),.review-field :deep(.el-textarea){display:block;margin-top:7px;width:100%}.review-checks{display:flex;flex-direction:column;align-items:flex-start;margin-top:12px}.review-checks :deep(.el-checkbox){height:auto;min-height:30px;margin:0;white-space:normal}.review-checks :deep(.el-checkbox__label){white-space:normal;line-height:1.7}.review-save{display:flex;justify-content:space-between;align-items:center;gap:12px;margin-top:15px;font-size:12px;color:#8190a4}.review-version{margin-top:24px;font-size:12px;color:#77879a}.review-version dl>div{display:grid;grid-template-columns:130px minmax(0,1fr);gap:10px;margin-top:8px}.review-version dd{margin:0;overflow-wrap:anywhere;font-family:monospace}.review-history{margin-top:24px;padding-top:20px;border-top:1px solid #e2e8ef}.review-history article{padding:12px 0;border-bottom:1px solid #edf0f4}.review-history header{display:flex;flex-wrap:wrap;align-items:center;gap:12px;font-size:12px}.review-history header span,.review-history small{color:#8390a1}.review-history p{font-size:12px;line-height:1.8;margin:8px 0;color:#5e7185}.review-history strong{font-weight:500}@media(max-width:760px){.review-comparison{grid-template-columns:1fr}.review-mesh-list{grid-template-columns:repeat(2,minmax(0,1fr))}.review-save{align-items:flex-start;flex-direction:column}.review-version dl>div{grid-template-columns:1fr}}
</style>
